import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String API_KEY = System.getenv("INTERNAL_API_KEY");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String authHeader = req.getHeader("X-Internal-Auth");
        if (authHeader == null || !authHeader.equals(API_KEY)) {
            resp.setStatus(403);
            resp.getWriter().write("{\"error\":\"forbidden\"}");
            return;
        }

        String department = req.getParameter("dept");
        String assetType = req.getParameter("type");
        String sortCol = req.getParameter("sort");

        if (department == null || department.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"dept parameter required\"}");
            return;
        }

        // Validate assetType against allowed enum
        if (assetType != null && !assetType.matches("^(laptop|desktop|monitor|phone|tablet)$")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid asset type\"}");
            return;
        }

        // Sort column - we allow dynamic ordering for the internal dashboard
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "asset_id";
        }

        StringBuilder query = new StringBuilder();
        query.append("SELECT asset_id, asset_name, asset_type, assigned_to, purchase_date ");
        query.append("FROM inventory.assets WHERE department = ? ");

        if (assetType != null) {
            query.append("AND asset_type = ? ");
        }

        // Dynamic ORDER BY - sort column is appended directly
        query.append("ORDER BY ").append(sortCol);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            stmt.setString(1, department);
            if (assetType != null) {
                stmt.setString(2, assetType);
            }

            logger.info("Executing asset query for dept=" + department + " sort=" + sortCol);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("asset_id", rs.getInt("asset_id"));
                row.put("asset_name", rs.getString("asset_name"));
                row.put("asset_type", rs.getString("asset_type"));
                row.put("assigned_to", rs.getString("assigned_to"));
                row.put("purchase_date", rs.getString("purchase_date"));
                results.put(row);
            }

            resp.setStatus(200);
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setStatus(405);
        resp.getWriter().write("{\"error\":\"method not allowed\"}");
    }
}
